examples.template:
MonarchKanbanBoard(
    columns = columns,
    key = { it.id },
    itemLabel = { it.title },
    modifier = Modifier.height(420.dp),
    onMove = { _, next ->
        columns = next
        // The app saves the move on its server here; throwing puts the card back.
    },
) { task, _ ->
    MonarchText(text = task.title, style = MonarchTextStyle.Label)
    MonarchBadge(text = task.tag, tone = task.tone)
}

examples.setupTemplate:
class Task(val id: String, val title: String, val tag: String, val tone: MonarchTone)
var columns by remember {
    mutableStateOf(
        listOf(
            MonarchKanbanColumn({{columns.0.id}}, {{columns.0.title}}, listOf(
                    Task({{columns.0.items.0.id}}, {{columns.0.items.0.title}}, {{columns.0.items.0.tag}}, {{columns.0.items.0.tone|tone}}),
                    Task({{columns.0.items.1.id}}, {{columns.0.items.1.title}}, {{columns.0.items.1.tag}}, {{columns.0.items.1.tone|tone}}),
                    Task({{columns.0.items.2.id}}, {{columns.0.items.2.title}}, {{columns.0.items.2.tag}}, {{columns.0.items.2.tone|tone}}),
                )),
            MonarchKanbanColumn({{columns.1.id}}, {{columns.1.title}}, listOf(
                    Task({{columns.1.items.0.id}}, {{columns.1.items.0.title}}, {{columns.1.items.0.tag}}, {{columns.1.items.0.tone|tone}}),
                    Task({{columns.1.items.1.id}}, {{columns.1.items.1.title}}, {{columns.1.items.1.tag}}, {{columns.1.items.1.tone|tone}}),
                    Task({{columns.1.items.2.id}}, {{columns.1.items.2.title}}, {{columns.1.items.2.tag}}, {{columns.1.items.2.tone|tone}}),
                ), wipLimit = {{columns.1.wipLimit}}),
            MonarchKanbanColumn({{columns.2.id}}, {{columns.2.title}}, listOf(
                    Task({{columns.2.items.0.id}}, {{columns.2.items.0.title}}, {{columns.2.items.0.tag}}, {{columns.2.items.0.tone|tone}}),
                )),
            MonarchKanbanColumn({{columns.3.id}}, {{columns.3.title}}, emptyList()),
        ),
    )
}

examples.setup:
class Task(val id: String, val title: String, val tag: String, val tone: MonarchTone)
var columns by remember {
    mutableStateOf(
        listOf(
            MonarchKanbanColumn("backlog", "Backlog", listOf(
                    Task("k1", "Draft release notes", "Docs", MonarchTone.Neutral),
                    Task("k2", "Audit colour contrast", "Design", MonarchTone.Info),
                    Task("k3", "Plan onboarding survey", "Research", MonarchTone.Neutral),
                )),
            MonarchKanbanColumn("doing", "In progress", listOf(
                    Task("k4", "Fix export timeout", "Bug", MonarchTone.Warning),
                    Task("k5", "Billing settings page", "Feature", MonarchTone.Info),
                    Task("k6", "Update help articles", "Docs", MonarchTone.Neutral),
                ), wipLimit = 2),
            MonarchKanbanColumn("review", "Review", listOf(
                    Task("k7", "Keyboard shortcuts", "Feature", MonarchTone.Info),
                )),
            MonarchKanbanColumn("done", "Done", emptyList()),
        ),
    )
}

